最小复现 Llama 名字规则的玩具树：
class Attn(nn.Module):
    def __init__(self):
        super().__init__()
        self.q_proj = nn.Linear(4, 4, bias=False)
class Model(nn.Module):
    def __init__(self, n):
        super().__init__()
        self.layers = nn.ModuleList([Attn() for _ in range(n)])
class ForCausalLM(nn.Module):
    def __init__(self, n):
        super().__init__()
        self.model = Model(n)
m = ForCausalLM(2)
print(list(m.state_dict().keys()))

